def maxDistance(moves):
    # Net horizontal and vertical displacement caused by the fixed moves
    x = 0
    y = 0
    # Number of wildcard moves
    free = 0
    for ch in moves:
        if ch == 'U':
            y += 1
        elif ch == 'D':
            y -= 1
        elif ch == 'L':
            x -= 1
        elif ch == 'R':
            x += 1
        else:
            # Each wildcard can always be aimed away from the origin
            free += 1
    # Every wildcard adds exactly 1 to the Manhattan distance
    return abs(x) + abs(y) + free
